import * as React from "react"

import { cn } from "@/lib/utils"

/*
  A FIELD STARTS WITH A CAPITAL — except where a capital would be wrong.

  `autoCapitalize` is the standards mechanism for it, and it is honest in a way
  a CSS transform is not: it changes what the SOFT KEYBOARD offers, so the
  value that gets stored is the value the reader saw. `text-transform:
  capitalize` would show one thing and save another, and `::first-letter` does
  not apply to an `<input>` at all.

  IT DOES NOTHING ON A DESKTOP KEYBOARD, deliberately — nothing here rewrites
  what somebody typed. A form that wants the first letter normalised on the way
  out does it at the form layer, where the rule can see the FIELD's meaning;
  see `DirectoryRecordSheet`.

  THE EXCEPTIONS ARE THE POINT. An email, a URL and a password are
  case-carrying strings where a capitalised first letter is either wrong or a
  failed login, and a numeric field has no letters to capitalise. Those get
  `none`, and a caller can still override any of it.
*/
const NEVER_CAPITALISE = ["email", "url", "password", "number", "tel"];

function Input({
  className,
  type,
  autoCapitalize,
  inputMode,
  ...props
}: React.ComponentProps<"input">) {
  const numeric = inputMode === "numeric" || inputMode === "decimal";
  return (
    <input
      type={type}
      inputMode={inputMode}
      autoCapitalize={
        autoCapitalize ??
        (numeric || (type && NEVER_CAPITALISE.includes(type)) ? "none" : "sentences")
      }
      data-slot="input"
      className={cn(
        "h-9 w-full min-w-0 rounded-md border border-input bg-fp-surface-1b px-3 py-1 text-base transition-[color,box-shadow] outline-none selection:bg-primary selection:text-primary-foreground file:inline-flex file:h-7 file:border-0 file:bg-transparent file:text-sm file:font-medium file:text-foreground placeholder:text-muted-foreground disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50 md:text-sm dark:bg-fp-field-fill",
        "focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/50",
        "aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40",
        className
      )}
      {...props}
    />
  )
}

export { Input }

import { X } from "lucide-react";

import { cn } from "@/lib/utils";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";

export interface MultiSelectListProps {
  options: string[];
  value: string[];
  onChange: (next: string[]) => void;
  /** Placeholder for the filter field. Omit the field entirely with `searchable={false}`. */
  placeholder?: string;
  /** Shown when the filter matches nothing. */
  empty?: string;
  /**
   * Give the list a filter field. Same rule as the filter panel's facets: a list
   * gets one when it cannot be taken in at once. Explicit, not a length
   * threshold.
   */
  searchable?: boolean;
  className?: string;
}

/**
 * Multi-select option list — **checkbox rows**, with the current selection as
 * removable chips above them.
 *
 * Why not `CommandItem`'s `selected` prop: that renders a small trailing check,
 * which is right for a **single**-select list because it marks *the* chosen row.
 * On a **multi**-select list it reads as "this is the current value" rather than
 * "tick as many as you like" — and before anything is chosen, a check-marked
 * list is visually identical to a single-select one, so people read it as
 * single-select and never discover they can pick more. Observed exactly that.
 *
 * The checkbox is `pointer-events-none` with `tabIndex={-1}` on purpose: the ROW
 * owns the click via `onSelect`, so letting the box take its own would toggle
 * twice and land back where it started. The row remains keyboard-operable
 * through cmdk, and the checkbox stays purely a visual indicator.
 *
 * ```tsx
 * <MultiSelectList
 *   options={products}
 *   value={selected}
 *   onChange={setSelected}
 *   placeholder="Search products…"
 * />
 * ```
 */
export function MultiSelectList({
  options,
  value,
  onChange,
  placeholder = "Search…",
  empty = "No matches.",
  searchable = true,
  className,
}: MultiSelectListProps) {
  const toggle = (option: string) =>
    onChange(
      value.includes(option)
        ? value.filter((v) => v !== option)
        : [...value, option]
    );

  return (
    <div className={cn("flex flex-col gap-2", className)}>
      {value.length > 0 && (
        <div className="flex flex-wrap gap-1.5">
          {value.map((v) => (
            <span
              key={v}
              className="inline-flex items-center gap-1 rounded-full bg-fp-card-1 py-0.5 pr-1 pl-2.5 text-xs text-foreground"
            >
              {v}
              <button
                type="button"
                aria-label={`Remove ${v}`}
                onClick={() => toggle(v)}
                className="rounded-full p-0.5 text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
              >
                <X className="size-3" />
              </button>
            </span>
          ))}
        </div>
      )}

      <Command className="rounded-md border border-border">
        {searchable && <CommandInput placeholder={placeholder} />}
        <CommandList>
          {searchable && <CommandEmpty>{empty}</CommandEmpty>}
          <CommandGroup>
            {options.map((option) => (
              <CommandItem
                key={option}
                value={option}
                onSelect={() => toggle(option)}
                aria-checked={value.includes(option)}
                icon={
                  <Checkbox
                    checked={value.includes(option)}
                    className="pointer-events-none"
                    tabIndex={-1}
                  />
                }
              >
                {option}
              </CommandItem>
            ))}
          </CommandGroup>
        </CommandList>
      </Command>
    </div>
  );
}

